mapper.select:

where del_flag = '0'
AND inbound_no like concat('%', #{inboundNo}, '%')
AND busi_type = #{busiType}
AND rela_customs_form_type = #{relaCustomsFormType}
AND doc_status = #{docStatus}
AND customs_status = #{customsStatus}
AND in_out_time >= #{params.beginInoutTime}
AND in_out_time <= #{params.endInoutTime}
order by id desc

mapper.update:
update br_inbound
inbound_no = #{inboundNo}, rela_ent_nm = #{relaEntNm}, busi_type = #{busiType}, rela_customs_form_type = #{relaCustomsFormType}, rela_customs_form_num = #{relaCustomsFormNum}, in_out_time = #{inOutTime}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where id = #{id}

mapper.select:
select i.*, m.material_name, m.material_cd, m.calc_unit, m.unit1, m.unit2 from br_inbound_item i
left join br_material m on m.id = i.material_id
where i.inbound_id = #{inboundId}
